package com.company.aiinterview.auth.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*; @Entity @Table(name="users") @Data @NoArgsConstructor @AllArgsConstructor @Builder public class UserEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String fullName; @Column(unique=true,nullable=false) private String email; private String passwordHash; private boolean active; private Instant createdAt; @ManyToMany(fetch=FetchType.EAGER) private Set<RoleEntity> roles; }
